UPDATE stretchy_report SET report_sql = "select c.external_id      as 'Client UID', c.display_name     as 'Client/Company Name',g.display_name as 'Group Name',cll.display_name as 'Representative', loancountTbl.incremental_count as Cycle,  cvg.code_value        as 'Gender',c.date_of_birth as 'Date of Birth',  cvs.code_value      as 'Strata', bi.`Business Sector` /*cvb.code_value    as 'Business Sector*/,bi.`Business Sub-Sector`,p.name as 'Loan Product', loanPurposeTble.code_value    as 'Purpose of the loan', l.principal_amount_proposed    as 'Applied Amount',l.submittedon_date as 'Submission Date', ld.due_diligence_recommended_amount as 'Due Diligence Recommended amount',  icReviewTbl.IC_Level_One      as 'IC Decision Level One', ld.ic_review_decision_level_one_on as 'IC Decision Level One Date', ld.ic_review_decision_level_one_recommended_amount as 'IC Decision Level One Recommended Amount', icReviewTbl.IC_Level_Two     as 'IC Decision Level Two', ld.ic_review_decision_level_two_on as 'IC Decision Level Two Date',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ld.ic_review_decision_level_two_recommended_amount as 'IC Decision Level Two Recommended Amount',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               icReviewTbl.IC_Level_Three     as 'IC Decision Level Three', ld.ic_review_decision_level_three_on as 'IC Decision Level Three Date',  ld.ic_review_decision_level_three_recommended_amount as 'IC Decision Level Three Recommended Amount', icReviewTbl.IC_Level_Four    as 'IC Decision Level Four', ld.ic_review_decision_level_four_on as 'IC Decision Level Four Date',ld.ic_review_decision_level_four_recommended_amount as 'IC Decision Level Four Recommended Amount', icReviewTbl.IC_Level_Five   as 'IC Decision Level Five', ld.ic_review_decision_level_five_on as 'IC Decision Level Five Date',ld.ic_review_decision_level_five_recommended_amount as 'IC Decision Level Five Recommended Amount',  case when l.loan_status_id = 500 or (l.loan_status_id=100 and (l.loan_decision_state in (1000,1200) or l.loan_decision_state is null)) then 0 else l.approved_icreview end as 'IC Approved Amount',l.approvedon_date AS 'Approval Date',l.repay_every as 'Repayment Frequency',case l.repayment_period_frequency_enum when 0 then 'Daily' when 1 then 'Weekly' when 2 then 'Monthly' when 3 then 'Yearly' end as 'Re-payment Term', l.term_frequency      as 'Loan Tenure in months',  ''       as 'IC Approved Amount in Words',    (instalmentAmntTbl.principal_amount+ifnull(instalmentAmntTbl.interest_amount,0)+ifnull(instalmentAmntTbl.fee_charges_amount,0)) as 'Installment Amount', coi.tax_identification_number         as 'Company Tin Number',  cvn.code_value      as 'Nationality', villageTbl.code_value     as 'Village', addr.physical_address_cell as 'Cell', addr.physical_address_sector as 'Sector', addr.physical_address_district as 'District',c.mobile_no as 'Mpesa/ Momo number ',cai.alt_phone_no as 'Fixed Phone Number',  coi.co_signors      as 'Cosigner Names',  l.account_no      as 'Loan ID Number',  coi.bank_account_number    as 'Bank Account Number',  coi.bank_name   as 'Bank Name',  ccma.UPI_NO     as 'UPI Number', villageTbl.code_value as 'Collateral Village', cellTbl.code_value     as 'Collateral Cell',  sectorTbl.code_value      as 'Collateral Sector', districtTbl.code_value    as 'Collateral District',  cvp.code_value    as 'Province',  ccma.collateral_owner_first           as 'Owners Name 1',  ccma.collateral_owner_second          as 'Owners Name 2',  ccma.id_no_of_collateral_owner_first  as 'Owners ID 1',  ccma.id_no_of_collateral_owner_second as 'Owners ID 2',  ccma.worth_of_collateral     as 'OMV Figures', concat(coalesce(nxtofkintbl.lastname,''),' ',coalesce(nxtofkintbl.firstname,'')) as 'Co-signer'/*coi.guarantor  as 'Co-signer'*/ , coi.national_identification_number as 'National/Refugee ID',  case                                                              when (con.enabled = false)                                                                  then loanStatusTable.loanStatus                                                              when con.enabled = true                                                                  then (case
                                                                                                                    when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.loanDecisionState ='Pending Approval'                                                                               then 'Pending Approval'
                                                                                                                    when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.loanDecisionState is null                                                                               then 'Review Application'                                                                           when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.next_loan_ic_review_decision_state =1900 then 'Prepare And Sign Contract'    when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.loan_decision_state =1000 then 'Due Diligence'  when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.loan_decision_state =1200 then 'IC Review Level One'  when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.next_loan_ic_review_decision_state =1500 then 'IC Review Level Two'  when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.next_loan_ic_review_decision_state =1600 then 'IC Review Level Three'  when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.next_loan_ic_review_decision_state =1700 then 'IC Review Level Four'  when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.next_loan_ic_review_decision_state =1800 then 'IC Review Level Five'        /*and                                                                                loanStatusTable.loanDecisionState != 'Prepare And Sign Contract'                                                                              then loanStatusTable.loanDecisionState when loanStatusTable.loanStatus ='Rejected'then 'Rejected'         */                                                                 /* when loanStatusTable.loanStatus != 'Pending Approval'                                                                               then loanStatusTable.loanStatus                                                                           when loanStatusTable.loanStatus = 'Pending Approval' and                                                                                loanStatusTable.loanDecisionState = 'Prepare And Sign Contract'                                                                               then loanStatusTable.loanStatus*/ else loanStatusTable.loanStatus end) end  as 'Loan Status',case when l.loan_status_id =200 then ld.prepare_and_sign_contract_on else ' ' end as 'Contract Upload Date',
                                         CONCAT(gt.firstname, ' ', gt.lastname) AS 'Guarantor Name', gt.mobile_number AS 'Guarantor Phone', gt.client_id AS 'Guarantor Client ID'   from m_office o  join m_office ounder ON ounder.hierarchy like concat(o.hierarchy, '%') AND  ounder.hierarchy like CONCAT('${currentUserHierarchy}', '%')
                                             join m_client c ON c.office_id = ounder.id   join m_loan l ON l.client_id = c.id      LEFT JOIN m_group_client gc ON gc.client_id = c.id   LEFT JOIN m_group g ON g.id = gc.group_id   left join m_client cll on cll.id = g.representative_id    left join m_loan_arrears_aging laa on laa.loan_id = l.id  join m_product_loan p ON p.id = l.product_id  left join m_code_value cvg ON cvg.id = c.gender_cv_id  left join m_client_other_info coi ON coi.client_id = c.id   left join m_client_additional_info cai on cai.client_id = c.id left join m_client_recruitment_survey crs on crs.client_id = c.id  left join m_code_value cvn ON cvn.id = coi.nationality_cv_id   left join m_code_value cvs ON cvs.id = coi.strata_cv_id   left join m_business_detail bd on bd.client_id = c.id   left join m_code_value cvb on cvb.id = bd.business_type_id   left join m_client_collateral_management lcm on lcm.client_id = c.id   left join m_client_collateral_management_additional_details ccma  on ccma.client_collateral_id = lcm.id    left join m_code_value cvp on cvp.id = ccma.province_cv_id    left join m_code_value loanPurposeTble on loanPurposeTble.id = l.loanpurpose_cv_id   left join m_code_value villageTbl on villageTbl.id = ccma.village_cv_id   left join m_code_value districtTbl on districtTbl.id = ccma.district_cv_id    left join m_code_value cellTbl on cellTbl.id = ccma.cell_cv_id  left join m_code_value sectorTbl on sectorTbl.id = ccma.sector_cv_id   left join m_client_address cla on cla.client_id= c.id left join m_address addr on addr.id = cla.address_id     left join (select ld.loan_id, case  when ld.loan_decision_state = 1000 then 'Review Application'  when ld.loan_decision_state = 1200 then 'Due Diligence'  when ld.loan_decision_state = 1300 then 'Collateral Review'  when ld.loan_decision_state = 1400 then 'IC Review Level One'  when ld.loan_decision_state = 1500 then 'IC Review Level Two'   when ld.loan_decision_state = 1600 then 'IC Review Level Three'  when ld.loan_decision_state = 1700 then 'IC Review Level Four'  when ld.loan_decision_state = 1800 then 'IC Review Level Five'  when ld.loan_decision_state = 1900 then 'Prepare And Sign Contract'  end    as loanDecisionState, ld.next_loan_ic_review_decision_state                                      as 'Next IC Level', if(ld.is_ic_review_decision_level_one_signed = true, 'Approved', if(ld.is_reject_ic_review_decision_level_one = true, 'Rejected', ''))   as 'IC_Level_One', if(ld.is_ic_review_decision_level_two_signed = true, 'Approved',  if(ld.is_reject_ic_review_decision_level_two = true, 'Rejected', ''))   as 'IC_Level_Two',  if(ld.is_ic_review_decision_level_three_signed = true, 'Approved',  if(ld.is_reject_ic_review_decision_level_three = true, 'Rejected', '')) as 'IC_Level_Three',  if(ld.is_ic_review_decision_level_four_signed = true, 'Approved',  if(ld.is_reject_ic_review_decision_level_four = true, 'Rejected', ''))  as 'IC_Level_Four',  if(ld.is_ic_review_decision_level_five_signed = true, 'Approved',  if(ld.is_reject_ic_review_decision_level_five = true, 'Rejected', ''))  as 'IC_Level_Five'  from m_loan_decision ld ) as icReviewTbl on icReviewTbl.loan_id = l.id left join m_loan_decision ld on ld.loan_id = l.id                                                   left join c_configuration con on con.name = 'Add-More-Stages-To-A-Loan-Life-Cycle'                                                    join (select l.id                                                as loanId,l.loan_decision_state,ld.next_loan_ic_review_decision_state,                                                                     case                                                                         when l.loan_status_id = 100 then 'Pending Approval'                                                                         when l.loan_status_id = 200 then 'Pending Disbursement'                                                                         when l.loan_status_id = 300 then 'Active'                                                                         when l.loan_status_id = 303 then 'Transfer In Progress'                                                                         when l.loan_status_id = 304 then 'Transfer On Hold'                                                                         when l.loan_status_id = 400 then 'Withdrawn By Client'                                                                         when l.loan_status_id = 500 then 'Rejected'                                                                         when l.loan_status_id = 600 then 'Closed Obligations Met'                                                                         when l.loan_status_id = 601 then 'Closed Written Off'                                                                         when l.loan_status_id = 602 then 'Closed Reschedule Outstanding Amount'                                                                         when l.loan_status_id = 700 then 'Overpaid' end as loanStatus,                                                                     case                                                                         when l.loan_decision_state = 1000 then 'Due Diligence'                                                                         when l.loan_decision_state = 1200 then 'IC Review Level One'                                                                        /* when l.loan_decision_state = 1300 then 'IC Review Level One'*/                                                                         when l.loan_decision_state = 1400 then 'IC Review Level Two'                                                                         when l.loan_decision_state = 1500 then 'IC Review Level Three'                                                                         when l.loan_decision_state = 1600 then 'IC Review Level Four'                                                                         when l.loan_decision_state = 1700 then 'IC Review Level Five'                                                                         when l.loan_decision_state = 1800 then 'Prepare And Sign Contract'                                                                         when l.loan_decision_state = 1900                                                                             then 'Pending Approval' end        as loanDecisionState                                                              from m_loan l                                                                       left join m_loan_decision ld on ld.loan_id = l.id ) as loanStatusTable                                                             on loanStatusTable.loanId = l.id     left join (select *from m_loan_repayment_schedule lt where                                                               lt.id in (select min(id) from m_loan_repayment_schedule rs   group by rs.loan_id)) instalmentAmntTbl on instalmentAmntTbl.loan_id = l.id
                                             left join ( SELECT      account_no,disbursedon_date,created_on_utc,submittedon_date,client_id,id as loan_id,     CAST(ROW_NUMBER() OVER (PARTITION BY client_id ORDER BY submittedon_date) AS SIGNED)AS incremental_count FROM      m_loan)loancountTbl on loancountTbl.client_id = l.client_id and loancountTbl.loan_id = l.id
                                             left join (select * from m_family_members fm where                                                               fm.id in (select min(id) from m_family_members rs   group by rs.client_id)) nxtofkintbl on nxtofkintbl.client_id = c.id
                                             left join `Business Information` bi on c.id =bi.client_id
                                         LEFT JOIN m_guarantor gt ON gt.loan_id=l.id
                                             where l.loan_status_id not in (300,600,602,700) and  o.id = ${officeId} and (l.product_id = '${loanProductId}' or '-1' = '${loanProductId}') and (ifnull(l.loan_officer_id, -10) = '${loanOfficerId}' or '-1' = '${loanOfficerId}') and (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId}) and (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId}) and (date(l.last_modified_on_utc) between date('${startDate}') and date('${endDate}'))  " WHERE id = (SELECT tbl.id FROM (SELECT sr.id FROM stretchy_report sr WHERE sr.report_name = "IC Minutes") AS tbl);
